    import re
    import math
    TRANSITION_PHRASES = ['furthermore', 'additionally', 'moreover', 'in addition', 'however', 'therefore', 'consequently', 'nevertheless', 'nonetheless', 'in contrast', 'on the other hand', 'as a result', 'in conclusion', 'in summary', 'for example', 'for instance', 'in particular', 'specifically', 'similarly', 'likewise', 'in fact', 'indeed', 'thus', 'hence', 'meanwhile', 'subsequently', 'finally', 'first', 'second', 'third', 'lastly', 'also', 'besides', 'still', 'yet', 'otherwise', 'instead', 'accordingly', 'subsequently', 'previously', 'overall', 'ultimately']

    def starts_with_transition(sentence):
        """Check if a sentence starts with a transition word or phrase."""
        s = sentence.strip().lower()
        for phrase in TRANSITION_PHRASES:
            pattern = '^' + re.escape(phrase) + '(?:[,;:\\s]|$)'
            if re.match(pattern, s):
                return True
        return False

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: ratio of sentences beginning with transition words/phrases to total sentences
        """
        sents = sentences(response)
        if not sents:
            score = 0.0
            return score
        transition_count = sum((1 for s in sents if starts_with_transition(s)))
        ratio = transition_count / len(sents)
        score = 0.0
        score += maximize(ratio)
        return score
    return grade


