    POSITIVE_WORDS = ['excellent', 'perfect', 'amazing', 'love', 'great', 'good', 'best', 'fantastic', 'wonderful', 'superb', 'outstanding', 'brilliant', 'awesome', 'terrific', 'exceptional', 'impressive', 'incredible', 'fabulous', 'magnificent', 'splendid', 'delightful', 'enjoyable', 'pleasant', 'pleased', 'happy', 'satisfied', 'satisfying', 'recommend', 'recommended', 'comfortable', 'comfortably', 'clear', 'crisp', 'smooth', 'easy', 'convenient', 'reliable', 'durable', 'sturdy', 'solid', 'quality', 'premium', 'superior', 'nice', 'lovely', 'beautiful', 'elegant', 'sleek', 'stylish', 'powerful', 'strong', 'effective', 'efficient', 'fast', 'quick', 'long', 'worth', 'worthy', 'value', 'affordable', 'reasonable', 'glad', 'thrilled', 'excited', 'enjoy', 'enjoyed', 'enjoying', 'like', 'liked', 'likes', 'loving', 'adore', 'adored', 'adores', 'praise', 'praised', 'praises', 'impress', 'impressed', 'impresses', 'stunning', 'remarkable', 'phenomenal', 'extraordinary', 'flawless', 'seamless', 'intuitive', 'responsive', 'accurate', 'precise', 'rich', 'deep', 'vibrant', 'lively', 'energetic', 'dynamic', 'robust', 'secure', 'stable', 'consistent', 'dependable', 'trustworthy', 'innovative', 'clever', 'smart', 'intelligent', 'sleek', 'compact', 'lightweight', 'portable', 'versatile', 'flexible', 'practical', 'useful', 'helpful', 'beneficial', 'positive', 'better', 'improved', 'upgrade', 'enhanced', 'boosted']
