        score += maximize(presence(count_terms(response, battery_terms) > 0))
        sound_terms = ['sound quality', 'audio quality', 'sound', 'audio', 'acoustics', 'bass', 'treble', 'midrange', 'mid-range', 'highs', 'lows', 'fidelity', 'clarity']
        score += maximize(presence(count_terms(response, sound_terms) > 0))
