        score += maximize(presence(count_terms(response, comfort_terms) > 0))
        price_terms = ['price', 'cost', 'value', 'affordable', 'expensive', 'cheap', 'pricing', 'worth', 'budget', 'dollar', 'dollars', 'money']
        score += maximize(presence(count_terms(response, price_terms) > 0))
