        score += maximize(presence(count_terms(response, noise_terms) > 0))
        connectivity_terms = ['connectivity', 'bluetooth', 'wireless', 'connection', 'connect', 'pairing', 'paired', 'wifi', 'wi-fi', 'range', 'signal', 'latency']
        score += maximize(presence(count_terms(response, connectivity_terms) > 0))
