    def count_terms(text, terms):
        """Total occurrences of any term (word or multiword phrase), case-insensitive.

        Single words match on word boundaries; phrases match as substrings.
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                n += len(re.findall(re.escape(t), low))
            else:
                n += len(re.findall('\\b' + re.escape(t) + '\\b', low))
        return n

    def word_count(text):
        return len(tokens(text))

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    def target_band(value, lo, hi=None, scale=1.0):
        """Best inside [lo, hi] (0.0); linearly worse outside, divided by `scale`.

        Use `scale` to keep the term comparable to count-based terms when the raw
        unit is large (e.g. scale=5 for a word-count band of width ~50).
        For an exact-value target pass hi=None (band collapses to lo).
        """
        if hi is None:
            hi = lo
        if value < lo:
            return float(-(lo - value) / scale)
        if value > hi:
            return float(-(value - hi) / scale)
        return 0.0

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: total word count is approximately 500 words
        Graded: maximize count of instances of the literary terms: 'symbolism', 'metaphor', 'irony', 'theme', 'characterization', 'foreshadowing', and 'allegory'
        """
        score = 0.0
        wc = word_count(response)
        score += target_band(wc, 450, 550, scale=50)
        literary_terms = ['symbolism', 'symbol', 'symbols', 'metaphor', 'metaphors', 'metaphorical', 'irony', 'ironic', 'ironically', 'theme', 'themes', 'thematic', 'characterization', 'characterizations', 'foreshadowing', 'foreshadow', 'foreshadowed', 'allegory', 'allegorical', 'allegories']
        score += maximize(count_terms(response, literary_terms))
        return score
    return grade


