    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_terms(text, terms):
        """Total occurrences of any term (word or multiword phrase), case-insensitive.

        Single words match on word boundaries; phrases match as substrings.
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                n += len(re.findall(re.escape(t), low))
            else:
                n += len(re.findall('\\b' + re.escape(t) + '\\b', low))
        return n

    def term_density(text, terms):
        """count_terms / total word count (for density / ratio / proportion metrics)."""
        return count_terms(text, terms) / max(1, len(tokens(text)))

    def word_count(text):
        return len(tokens(text))

    def target_band(value, lo, hi=None, scale=1.0):
        """Best inside [lo, hi] (0.0); linearly worse outside, divided by `scale`.

        Use `scale` to keep the term comparable to count-based terms when the raw
        unit is large (e.g. scale=5 for a word-count band of width ~50).
        For an exact-value target pass hi=None (band collapses to lo).
        """
        if hi is None:
            hi = lo
        if value < lo:
            return float(-(lo - value) / scale)
        if value > hi:
            return float(-(value - hi) / scale)
        return 0.0

    def presence(condition):
        """1.0 if a stated yes/no requirement is met, else 0.0."""
        return 1.0 if condition else 0.0

    async def grade(response, llm_grader, embedding_model):
        """
        Skipped: maximize semantic coherence (LLM-based term removed)
        Skipped: maximize factual density (LLM-based term removed)
        Skipped: maximize user helpfulness (LLM-based term removed)
        Graded: appropriate review length as a factor (target_band on word count)
        Graded: maximize usage of specific technical terminology (term_density of listed terms)
        Graded: structured format with clear pros/cons sections (single llm_count boolean classification)
        """
        score = 0.0
        wc = word_count(response)
        score += target_band(wc, lo=150, hi=600, scale=50)
        tech_terms = ['active noise cancellation', 'active noise-cancellation', 'frequency response', 'impedance', 'codec', 'codecs', 'latency', 'driver', 'drivers', 'anc', 'bluetooth', 'aptx', 'ldac', 'aac', 'sbc', 'decibel', 'db', 'ohm', 'ohms', 'hz', 'khz', 'noise cancelling', 'noise canceling', 'noise-cancelling', 'noise-canceling']
        score += 100 * term_density(response, tech_terms)
        has_proscons = await llm_count(response, 'Does this contain a structured pros vs cons list? Answer 1 for yes, 0 for no.', llm_grader=llm_grader) >= 1
        score += presence(has_proscons) * 10
        return score
    return grade


