def _build_nl_gameable_srh_nl_filtered_25():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_distinct_terms(text, terms):
        """How many DISTINCT terms from the list appear at least once.

        For coverage metrics: "mentions at least N of the following features",
        "includes keywords from the topic set", "defines M of the terms".
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                hit = re.search(re.escape(t), low)
            else:
                hit = re.search('\\b' + re.escape(t) + '\\b', low)
            if hit:
                n += 1
        return n

    def word_count(text):
        return len(tokens(text))

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)
    ORIGINAL = 'The primary goal of our new strategy is to ensure that customer satisfaction is significantly improved. This will involve enhancing our customer support services, streamlining communication channels, and actively seeking feedback to address any issues promptly.'
    ORIGINAL_WORD_COUNT = len(tokens(ORIGINAL))
    ESSENTIAL_PHRASES = ['customer satisfaction', 'customer support', 'communication channels', 'feedback', 'strategy', 'goal', 'streamlin', 'enhanc', 'address', 'issues']

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: maximize the percentage reduction in word count compared to the original passage
        Graded: retain all essential phrases from the original passage
        """
        score = 0.0
        response_wc = word_count(response)
        if ORIGINAL_WORD_COUNT > 0:
            pct_reduction = (ORIGINAL_WORD_COUNT - response_wc) / ORIGINAL_WORD_COUNT * 100.0
        else:
            pct_reduction = 0.0
        score += maximize(pct_reduction)
        distinct_retained = count_distinct_terms(response, ESSENTIAL_PHRASES)
        score += maximize(distinct_retained * 5.0)
        return score
    return grade


