def _build_nl_gameable_srh_nl_filtered_93():
    import re
    import math

    def syllables(word):
        """Crude syllable count for one word (vowel groups, silent-e heuristic)."""
        word = word.lower()
        n = len(re.findall('[aeiouy]+', word))
        if word.endswith('e') and n > 1:
            n -= 1
        return max(1, n)

    def count_terms(text, terms):
        """Total occurrences of any term (word or multiword phrase), case-insensitive.

        Single words match on word boundaries; phrases match as substrings.
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                n += len(re.findall(re.escape(t), low))
            else:
                n += len(re.findall('\\b' + re.escape(t) + '\\b', low))
        return n

    def line_syllable_pattern_score(text, pattern):
        """0.0 when each non-empty line's syllable count matches `pattern`
        (e.g. [5, 7, 5] for a haiku); else minus the total absolute deviation
        (including missing/extra lines, each costing its expected count)."""
        lines_ = [ln.strip() for ln in text.split('\n') if ln.strip()]
        dev = 0.0
        for i, expected in enumerate(pattern):
            if i < len(lines_):
                got = sum((syllables(w) for w in re.findall("[A-Za-z']+", lines_[i])))
                dev += abs(got - expected)
            else:
                dev += expected
        for ln in lines_[len(pattern):]:
            dev += sum((syllables(w) for w in re.findall("[A-Za-z']+", ln)))
        return -dev

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: adhere to the traditional 5-7-5 syllable structure
        Graded: maximize the count of words related to the natural world
        """
        score = 0.0
        score += maximize(line_syllable_pattern_score(response, [5, 7, 5]))
