def _build_nl_gameable_srh_nl_filtered_103():
    import re
    import math

    def count_distinct_terms(text, terms):
        """How many DISTINCT terms from the list appear at least once.

        For coverage metrics: "mentions at least N of the following features",
        "includes keywords from the topic set", "defines M of the terms".
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                hit = re.search(re.escape(t), low)
            else:
                hit = re.search('\\b' + re.escape(t) + '\\b', low)
            if hit:
                n += 1
        return n

    def _rhyme_tail(word):
        """Crude rhyme key: last vowel group + everything after it."""
        m = re.search('[aeiouy]+[^aeiouy]*$', word.lower())
        return m.group(0) if m else word.lower()

    def count_rhyming_pairs(text):
        """Pairs of lines (any two) whose final words share a crude rhyme tail."""
        ends = []
        for ln in text.split('\n'):
            ws = re.findall("[A-Za-z']+", ln)
            if ws:
                ends.append(_rhyme_tail(ws[-1]))
        n = 0
        for i in range(len(ends)):
            for j in range(i + 1, len(ends)):
                if ends[i] == ends[j]:
                    n += 1
        return n

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: maximize the count of rhyming pairs
        Graded: maximize the count of topical keywords included from the set: 'trees', 'leaves', 'green', 'wild', 'bark', 'canopy'
        """
        score = 0.0
        score += maximize(count_rhyming_pairs(response))
        keywords = ['trees', 'leaves', 'green', 'wild', 'bark', 'canopy']
        score += maximize(count_distinct_terms(response, keywords))
        return score
    return grade


