def _build_nl_gameable_srh_nl_filtered_125():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_distinct_terms(text, terms):
        """How many DISTINCT terms from the list appear at least once.

        For coverage metrics: "mentions at least N of the following features",
        "includes keywords from the topic set", "defines M of the terms".
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                hit = re.search(re.escape(t), low)
            else:
                hit = re.search('\\b' + re.escape(t) + '\\b', low)
            if hit:
                n += 1
        return n

    def word_count(text):
        return len(tokens(text))

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    def minimize(value):
        """Lower raw value = better on this criterion."""
        return float(-value)
    KEY_TERMS = ['quick', 'brown', 'fox', 'jumps', 'lazy', 'dog', 'sentence', 'typing', 'exercises', 'letter', 'english', 'alphabet', 'font', 'types', 'testing', 'keyboard', 'layouts']
    ORIGINAL_WORD_COUNT = 57

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: minimize total word count (fewer words = better score)
        Graded: retain all key terms from the original paragraph (count_distinct_terms of key content words)
        """
        score = 0.0
        wc = word_count(response)
        score += minimize(wc / ORIGINAL_WORD_COUNT * 17)
        distinct = count_distinct_terms(response, KEY_TERMS)
        score += maximize(distinct)
        return score
    return grade


