def _build_nl_gameable_srh_nl_filtered_136():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def sentences(text):
        """Non-empty sentence strings, split on . ! ?"""
        return [p.strip() for p in re.split('[.!?]+', text) if p.strip()]

    def syllables(word):
        """Crude syllable count for one word (vowel groups, silent-e heuristic)."""
        word = word.lower()
        n = len(re.findall('[aeiouy]+', word))
        if word.endswith('e') and n > 1:
            n -= 1
        return max(1, n)

    def avg_sentence_length(text):
        """Mean words per sentence."""
        return len(tokens(text)) / max(1, len(sentences(text)))

    def count_polysyllabic(text, min_syllables=3):
        """Words with at least `min_syllables` syllables."""
        return sum((1 for t in tokens(text) if syllables(t) >= min_syllables))

    def gunning_fog_index(text):
        """Fog: 0.4*((words/sentences) + 100*(polysyllables/words)). Higher = harder."""
        nw = max(1, len(tokens(text)))
        ns = max(1, len(sentences(text)))
        poly = count_polysyllabic(text)
        return 0.4 * (nw / ns + 100.0 * (poly / nw))

    def minimize(value):
        """Lower raw value = better on this criterion."""
        return float(-value)

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: Gunning Fog Index score should be low
        Graded: average sentence length should be short
        Graded: count of complex words (three or more syllables) should be minimized
        """
        score = 0.0
        score += minimize(gunning_fog_index(response))
        score += minimize(avg_sentence_length(response))
        score += minimize(count_polysyllabic(response, min_syllables=3))
        return score
    return grade


