def _build_nl_gameable_srh_nl_filtered_144():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_distinct_terms(text, terms):
        """How many DISTINCT terms from the list appear at least once.

        For coverage metrics: "mentions at least N of the following features",
        "includes keywords from the topic set", "defines M of the terms".
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                hit = re.search(re.escape(t), low)
            else:
                hit = re.search('\\b' + re.escape(t) + '\\b', low)
            if hit:
                n += 1
        return n

    def word_count(text):
        return len(tokens(text))

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    def target_band(value, lo, hi=None, scale=1.0):
        """Best inside [lo, hi] (0.0); linearly worse outside, divided by `scale`.

        Use `scale` to keep the term comparable to count-based terms when the raw
        unit is large (e.g. scale=5 for a word-count band of width ~50).
        For an exact-value target pass hi=None (band collapses to lo).
        """
        if hi is None:
            hi = lo
        if value < lo:
            return float(-(lo - value) / scale)
        if value > hi:
            return float(-(value - hi) / scale)
        return 0.0
    ORIGINAL_ARTICLE = 'The rise of electric vehicles (EVs) marks a significant shift in the automotive industry. With growing environmental concerns and advancements in battery technology, EVs are becoming more popular among consumers. Major car manufacturers are investing heavily in EV production, with some even announcing plans to phase out gasoline-powered cars entirely. Government incentives and policies are also playing a crucial role in promoting the adoption of EVs. However, challenges such as charging infrastructure and battery recycling need to be addressed to ensure the widespread adoption of electric vehicles. As technology continues to evolve, the future of transportation seems to be leaning towards sustainable and efficient energy solutions.'
    KEY_TERMS = ['electric vehicles', 'electric vehicle', 'battery technology', 'charging infrastructure', 'government incentives', 'government incentive', 'sustainable']

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: inclusion of key terms from the article (explicit quoted keyword list)
        Graded: summary word count is approximately 30% of the original article's word count
        """
        score = 0.0
        distinct = count_distinct_terms(response, KEY_TERMS)
        score += maximize(distinct)
        original_wc = word_count(ORIGINAL_ARTICLE)
        target_wc = 0.3 * original_wc
        tolerance = 0.05 * original_wc
        response_wc = word_count(response)
        score += target_band(response_wc, target_wc - tolerance, target_wc + tolerance, scale=1.0)
        return score
    return grade


