def _build_nl_gameable_srh_nl_filtered_193():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def sentences(text):
        """Non-empty sentence strings, split on . ! ?"""
        return [p.strip() for p in re.split('[.!?]+', text) if p.strip()]

    def automated_readability_index(text):
        """ARI: 4.71*(chars/words) + 0.5*(words/sentences) - 21.43. Higher = harder."""
        toks = tokens(text)
        nw = max(1, len(toks))
        ns = max(1, len(sentences(text)))
        nchars = sum((len(t) for t in toks))
        return 4.71 * (nchars / nw) + 0.5 * (nw / ns) - 21.43

    def minimize(value):
        """Lower raw value = better on this criterion."""
        return float(-value)

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: Automated Readability Index (ARI) score — minimize (lower ARI = simpler/more readable text, matching the simplification goal)
        Skipped (instruction, not computed by the tool): minimize average word length in characters — internal ARI ingredient, not a separate stated metric
        Skipped (instruction, not computed by the tool): minimize average sentence length in words — internal ARI ingredient, not a separate stated metric
        """
        score = 0.0
        score += minimize(automated_readability_index(response))
        return score
    return grade


