        score = 0.0
        running_shoes_density = term_density(response, ['running shoes'])
        score += target_band(running_shoes_density, 0.03, 0.05, scale=0.01)
        hp_density = term_density(response, ['high-performance', 'high performance'])
        score += target_band(hp_density, 0.03, 0.05, scale=0.01)
        durable_density = term_density(response, ['durable', 'durability', 'durably'])
        score += target_band(durable_density, 0.03, 0.05, scale=0.01)
        breathable_density = term_density(response, ['breathable', 'breathability', 'breathe', 'breathing'])
