def _build_nl_gameable_srh_nl_filtered_239():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def sentences(text):
        """Non-empty sentence strings, split on . ! ?"""
        return [p.strip() for p in re.split('[.!?]+', text) if p.strip()]

    def syllables(word):
        """Crude syllable count for one word (vowel groups, silent-e heuristic)."""
        word = word.lower()
        n = len(re.findall('[aeiouy]+', word))
        if word.endswith('e') and n > 1:
            n -= 1
        return max(1, n)

    def flesch_reading_ease(text):
        """206.835 - 1.015*(words/sentences) - 84.6*(syllables/words). Higher = easier."""
        nw = max(1, len(tokens(text)))
        ns = max(1, len(sentences(text)))
        nsyl = sum((syllables(w) for w in tokens(text)))
        return 206.835 - 1.015 * (nw / ns) - 84.6 * (nsyl / nw)

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: Flesch Reading Ease score should be high (indicating greater readability)
        Skipped (instruction, not computed by the tool): average number of words per sentence should be low (shorter sentences) — this is a description of what Flesch Reading Ease considers, not a separate metric
        Skipped (instruction, not computed by the tool): average number of syllables per word should be low (simpler words) — this is a description of what Flesch Reading Ease considers, not a separate metric
        """
        score = 0.0
        score += maximize(flesch_reading_ease(response))
        return score
    return grade


