def _build_nl_gameable_srh_nl_filtered_277():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_terms(text, terms):
        """Total occurrences of any term (word or multiword phrase), case-insensitive.

        Single words match on word boundaries; phrases match as substrings.
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                n += len(re.findall(re.escape(t), low))
            else:
                n += len(re.findall('\\b' + re.escape(t) + '\\b', low))
        return n

    def term_density(text, terms):
        """count_terms / total word count (for density / ratio / proportion metrics)."""
        return count_terms(text, terms) / max(1, len(tokens(text)))

    def target_band(value, lo, hi=None, scale=1.0):
        """Best inside [lo, hi] (0.0); linearly worse outside, divided by `scale`.

        Use `scale` to keep the term comparable to count-based terms when the raw
        unit is large (e.g. scale=5 for a word-count band of width ~50).
        For an exact-value target pass hi=None (band collapses to lo).
        """
        if hi is None:
            hi = lo
        if value < lo:
            return float(-(lo - value) / scale)
        if value > hi:
            return float(-(value - hi) / scale)
        return 0.0

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: keyword density for 'eco-friendly' at 3%
        Graded: keyword density for 'sustainable' at 3%
        Graded: keyword density for 'reusable' at 3%
        Graded: keyword density for 'water bottle' at 3%
        """
        score = 0.0
        target = 0.03
        eco_density = term_density(response, ['eco-friendly', 'eco friendly'])
        score += target_band(eco_density, target, target, scale=0.01)
        sustainable_density = term_density(response, ['sustainable', 'sustainability', 'sustainably'])
        score += target_band(sustainable_density, target, target, scale=0.01)
        reusable_density = term_density(response, ['reusable', 'reuse', 'reusing', 'reused'])
        score += target_band(reusable_density, target, target, scale=0.01)
        water_bottle_density = term_density(response, ['water bottle', 'water bottles'])
        score += target_band(water_bottle_density, target, target, scale=0.01)
        return score
    return grade


