    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_terms(text, terms):
        """Total occurrences of any term (word or multiword phrase), case-insensitive.

        Single words match on word boundaries; phrases match as substrings.
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                n += len(re.findall(re.escape(t), low))
            else:
                n += len(re.findall('\\b' + re.escape(t) + '\\b', low))
        return n

    def word_count(text):
        return len(tokens(text))

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    def minimize(value):
        """Lower raw value = better on this criterion."""
        return float(-value)

    def target_band(value, lo, hi=None, scale=1.0):
        """Best inside [lo, hi] (0.0); linearly worse outside, divided by `scale`.

        Use `scale` to keep the term comparable to count-based terms when the raw
        unit is large (e.g. scale=5 for a word-count band of width ~50).
        For an exact-value target pass hi=None (band collapses to lo).
        """
        if hi is None:
            hi = lo
        if value < lo:
            return float(-(lo - value) / scale)
        if value > hi:
            return float(-(value - hi) / scale)
        return 0.0

    def presence(condition):
        """1.0 if a stated yes/no requirement is met, else 0.0."""
        return 1.0 if condition else 0.0

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: total word count does not exceed 150 words (target_band, penalize over 150)
        Graded: presence of the key term 'climate change'
        Graded: presence of the key term 'polar bears'
        Graded: presence of the key term 'melting ice'
        Graded: presence of the key term 'habitat loss'
        Graded: minimize total word count (shorter summaries score higher, provided key terms are included)
        """
        score = 0.0
        wc = word_count(response)
        score += target_band(wc, 0, 150, scale=10)
        score += maximize(presence(count_terms(response, ['climate change']) > 0))
        score += maximize(presence(count_terms(response, ['polar bear', 'polar bears']) > 0))
        score += maximize(presence(count_terms(response, ['melting ice']) > 0))
        score += maximize(presence(count_terms(response, ['habitat loss']) > 0))
        score += minimize(wc / 10.0)
        return score
    return grade


