def _build_nl_gameable_srh_nl_filtered_323():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def sentences(text):
        """Non-empty sentence strings, split on . ! ?"""
        return [p.strip() for p in re.split('[.!?]+', text) if p.strip()]

    def syllables(word):
        """Crude syllable count for one word (vowel groups, silent-e heuristic)."""
        word = word.lower()
        n = len(re.findall('[aeiouy]+', word))
        if word.endswith('e') and n > 1:
            n -= 1
        return max(1, n)

    def flesch_kincaid_grade(text):
        """0.39*(words/sentences) + 11.8*(syllables/words) - 15.59. Higher = harder."""
        nw = max(1, len(tokens(text)))
        ns = max(1, len(sentences(text)))
        nsyl = sum((syllables(w) for w in tokens(text)))
        return 0.39 * (nw / ns) + 11.8 * (nsyl / nw) - 15.59

    def minimize(value):
        """Lower raw value = better on this criterion."""
        return float(-value)

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: Flesch-Kincaid grade level score below 8.0
        """
        score = 0.0
        fk = flesch_kincaid_grade(response)
        score += minimize(fk)
        return score
    return grade


