def _build_nl_gameable_srh_nl_filtered_334():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_distinct_terms(text, terms):
        """How many DISTINCT terms from the list appear at least once.

        For coverage metrics: "mentions at least N of the following features",
        "includes keywords from the topic set", "defines M of the terms".
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                hit = re.search(re.escape(t), low)
            else:
                hit = re.search('\\b' + re.escape(t) + '\\b', low)
            if hit:
                n += 1
        return n

    def word_count(text):
        return len(tokens(text))

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)

    def target_band(value, lo, hi=None, scale=1.0):
        """Best inside [lo, hi] (0.0); linearly worse outside, divided by `scale`.

        Use `scale` to keep the term comparable to count-based terms when the raw
        unit is large (e.g. scale=5 for a word-count band of width ~50).
        For an exact-value target pass hi=None (band collapses to lo).
        """
        if hi is None:
            hi = lo
        if value < lo:
            return float(-(lo - value) / scale)
        if value > hi:
            return float(-(value - hi) / scale)
        return 0.0
    KEY_TERMS = ['artificial intelligence', 'ai', 'healthcare', 'health care', 'autonomous vehicles', 'autonomous vehicle', 'bias', 'accountability', 'privacy', 'automating', 'automate', 'automation', 'data analysis', 'patient outcomes', 'patient outcome', 'personalize', 'personalized', 'personalizing', 'treatment', 'administrative', 'automotive', 'driver-assistance', 'driver assistance', 'ethical', 'ethics', 'policymakers', 'policymaker', 'societal', 'advancements', 'advancement']

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: inclusion of key terms from the original article text
        Graded: summary length ideally around 80 words
        """
        score = 0.0
        score += maximize(count_distinct_terms(response, KEY_TERMS))
        wc = word_count(response)
        score += target_band(wc, 70, 90, scale=10)
        return score
    return grade


