    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_terms(text, terms):
        """Total occurrences of any term (word or multiword phrase), case-insensitive.

        Single words match on word boundaries; phrases match as substrings.
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                n += len(re.findall(re.escape(t), low))
            else:
                n += len(re.findall('\\b' + re.escape(t) + '\\b', low))
        return n

    def word_count(text):
        return len(tokens(text))

    def target_band(value, lo, hi=None, scale=1.0):
        """Best inside [lo, hi] (0.0); linearly worse outside, divided by `scale`.

        Use `scale` to keep the term comparable to count-based terms when the raw
        unit is large (e.g. scale=5 for a word-count band of width ~50).
        For an exact-value target pass hi=None (band collapses to lo).
        """
        if hi is None:
            hi = lo
        if value < lo:
            return float(-(lo - value) / scale)
        if value > hi:
            return float(-(value - hi) / scale)
        return 0.0

    def presence(condition):
        """1.0 if a stated yes/no requirement is met, else 0.0."""
        return 1.0 if condition else 0.0

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: minimum word count of 60 words
        Graded: presence of the term 'artificial intelligence'
        Graded: presence of the term 'healthcare'
        Graded: presence of the term 'finance'
        Graded: presence of the term 'education'
        Graded: presence of the term 'ethics'
        Skipped (instruction, not computed by the tool): inclusion of primary points from the article
        """
        score = 0.0
        score += target_band(word_count(response), 60, hi=None, scale=1.0)
        score += presence(count_terms(response, ['artificial intelligence']) > 0)
        score += presence(count_terms(response, ['healthcare', 'health care']) > 0)
        score += presence(count_terms(response, ['finance', 'financial']) > 0)
        score += presence(count_terms(response, ['education', 'educational']) > 0)
        score += presence(count_terms(response, ['ethics', 'ethical']) > 0)
        return score
    return grade


