def _build_nl_gameable_srh_nl_filtered_351():
    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def count_distinct_terms(text, terms):
        """How many DISTINCT terms from the list appear at least once.

        For coverage metrics: "mentions at least N of the following features",
        "includes keywords from the topic set", "defines M of the terms".
        """
        low = text.lower()
        n = 0
        for t in terms:
            t = str(t).lower().strip()
            if not t:
                continue
            if re.search('[^\\w]', t):
                hit = re.search(re.escape(t), low)
            else:
                hit = re.search('\\b' + re.escape(t) + '\\b', low)
            if hit:
                n += 1
        return n

    def word_count(text):
        return len(tokens(text))

    def maximize(value):
        """Higher raw value = better on this criterion."""
        return float(value)
    ORIGINAL_TEXT = 'The development of artificial neural networks has led to significant breakthroughs in the field of artificial intelligence. These networks are capable of learning from vast amounts of data, enabling machines to perform tasks previously thought to require human intelligence. This has applications in various domains, such as healthcare, finance, and autonomous driving.'
    ORIGINAL_WORD_COUNT = word_count(ORIGINAL_TEXT)
    KEY_TERMS = ['artificial neural networks', 'artificial intelligence', 'learning', 'data', 'machines', 'tasks', 'human intelligence', 'healthcare', 'finance', 'autonomous driving', 'breakthroughs', 'applications']

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: maximize the percentage reduction in word count relative to the original paragraph
        Graded: ensure all key terms from the original paragraph are present in the rewritten text
        """
        score = 0.0
        rewritten_wc = word_count(response)
        pct_reduction = (ORIGINAL_WORD_COUNT - rewritten_wc) / ORIGINAL_WORD_COUNT * 100.0
        score += maximize(pct_reduction)
        distinct_found = count_distinct_terms(response, KEY_TERMS)
        score += maximize(distinct_found * (100.0 / len(KEY_TERMS)))
        return score
    return grade


