    import re
    import math

    def tokens(text):
        """Lowercased word tokens (letters + apostrophes)."""
        return re.findall("[A-Za-z']+", text.lower())

    def sentences(text):
        """Non-empty sentence strings, split on . ! ?"""
        return [p.strip() for p in re.split('[.!?]+', text) if p.strip()]

    def avg_sentence_length(text):
        """Mean words per sentence."""
        return len(tokens(text)) / max(1, len(sentences(text)))

    def avg_word_length(text):
        """Mean characters per word token."""
        toks = tokens(text)
        return sum((len(t) for t in toks)) / max(1, len(toks))

    def minimize(value):
        """Lower raw value = better on this criterion."""
        return float(-value)

    async def grade(response, llm_grader, embedding_model):
        """
        Graded: minimize average word length
        Graded: minimize average sentence length
        """
        score = 0.0
        score += minimize(avg_word_length(response))
        score += minimize(avg_sentence_length(response))
        return score
    return grade


